154	bool SARBackproject::fetchRadarData() {
155	
156	    // SLOWTIME DATA
157	    std::ifstream st_file(this->m_st_dataset_filename);
158	    if (!st_file.is_open()) {
159	        std::cerr << "Error opening slowtime dataset!" << std::endl;
160	        return 1;
161	    }
162	    std::string line;
163	    int pulse_idx = 0;
164	    while (std::getline(st_file, line) && pulse_idx < PULSES) {
165	        std::stringstream ss(line);
166	        std::string value;
167	
168	        // Read each column from the line and store in respective array
169	        std::getline(ss, value, ',');
170	        this->m_broadcast_data_array[BC_ELEMENTS*pulse_idx] = std::stof(value);
171	
172	        std::getline(ss, value, ',');
173	        this->m_broadcast_data_array[BC_ELEMENTS*pulse_idx + 1] = std::stof(value);
174	
175	        std::getline(ss, value, ',');
176	        this->m_broadcast_data_array[BC_ELEMENTS*pulse_idx + 2] = std::stof(value);
177	
178	        std::getline(ss, value, ',');
179	        this->m_broadcast_data_array[BC_ELEMENTS*pulse_idx + 3] = std::stof(value);
180	
181	        pulse_idx++;
182	    }
183	    
184	    // RANGE COMPRESSED DATA
185	    std::ifstream rc_file(this->m_rc_dataset_filename);
186	    if (!rc_file.is_open()) {
187	        std::cerr << "Error opening range compressed dataset!" << std::endl;
188	        return 1;
189	    }
190	    pulse_idx = 0;
191	    while (std::getline(rc_file, line) && pulse_idx < PULSES) {
192	        std::stringstream ss(line);
193	        std::string value;
194	        int rc_samp_cnt = 0;
195	
196	        // Read each column (complex number) from the line and store in array
197	        while (std::getline(ss, value, ',') && rc_samp_cnt < RC_SAMPLES) {
198	            std::regex complex_regex(R"(([+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)([+-](?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)i)");
199	            std::smatch match;
200	            std::regex_search(value, match, complex_regex);
201	
202	            float real_part = std::stof(match[1].str());
203	            float imag_part = std::stof(match[2].str());
204	
205	            // Store the complex number in the array
206	            this->m_rc_array[pulse_idx*RC_SAMPLES + rc_samp_cnt] = (cfloat) {real_part, imag_part};
207	
208	            rc_samp_cnt++;
209	        }
210	        rc_samp_cnt = 0;
211	        pulse_idx++;
212	    }
213	
214	    return 0;
215	}
