217	void SARBackproject::genTargetPixels() {
218	    // AZIMUTH RESOLUTION GRID
219	    double az_res = 0;
220	    double half_az_width = 0;
221	    double delta_az;
222	    double total_az;
223	    if (PULSES != 1) {
224	        double az_ant[PULSES];
225	        for (int i = 0; i < PULSES; i++) {
226	            // atan2(y_ant_pos / x_ant_pos)
227	            az_ant[i] = std::atan2(this->m_broadcast_data_array[BC_ELEMENTS*i + 1], this->m_broadcast_data_array[BC_ELEMENTS*i]);
228	        }
229	        this->unwrap(az_ant);
230	        double sum_diff = 0.0;
231	        for (int i = 1; i < PULSES; i++) {
232	            sum_diff += (az_ant[i] - az_ant[i - 1]);
233	        }
234	        double mean_diff = sum_diff / (PULSES - 1);
235	        delta_az = std::fabs(mean_diff);
236	        double min_az = *std::min_element(az_ant, az_ant + PULSES);
237	        double max_az = *std::max_element(az_ant, az_ant + PULSES);
238	        total_az = max_az - min_az;
239	        az_res = C/(2.0*total_az*MIN_FREQ);
240	        double az_width = C/(2.0*delta_az*MIN_FREQ);
241	        half_az_width = az_width/2.0;
242	    }
243	
244	    // Determine the maximum scene size of the image (m)
245	    double max_wr = C/(2*RANGE_FREQ_STEP);
246	    double max_wx = C/(2*delta_az*MIN_FREQ);
247	
248	    // Determine the resolution of the image (m)
249	    double dr = C/(2*RANGE_FREQ_STEP*424);
250	    double dx = C/(2*total_az*MIN_FREQ);
251	
252	    printf("Total Az: %.1f deg, %.4f rad\n", total_az*(180.0/PI), total_az);
253	    printf("Maximum Scene Size: %.2f m range, %.2f m cross-range\n", max_wr, max_wx);
254	    printf("Resolution: %.2fm range, %.2f m cross-range\n", dr, dx);
255	
256	    int idx = 0;
257	    for(int pulse_idx = 0; pulse_idx < PULSES; pulse_idx++) {
258	        for(int rng_idx = 0; rng_idx < RC_SAMPLES; rng_idx++) {
259	
260	            // X target pixels
261	            this->m_xyz_px_array[idx++] = (rng_idx-HALF_RANGE_SAMPLES)*RANGE_RES;
262	
263	            // Y target pixels
264	            this->m_xyz_px_array[idx++] = az_res*pulse_idx - half_az_width;
265	
266	            // Z target pixels
267	            this->m_xyz_px_array[idx++] = 0.0;
268	        }
269	    }
270	}
271	
272	void SARBackproject::runGraphs() {
273	    // Run graphs indefinitely (instead of for specific amount of iterations)
274	    for(int i = 0; i < this->m_instances; i++) {
275	        this->m_bp_graph_hdls[i].run(0);
276	    }
277	}
