13	void px_demux_kern(input_stream<float>* __restrict px_xyz_in,
14	                   output_pktstream *px_xyz_out) {
15	    
16	
17	    // 3-bit pattern to identify the type of packet
18	    int pkt_type = 0;
19	    
20	    // Pixel components per AI reconstruction kernel
21	    int px_components_per_ai = ((PULSES*RC_SAMPLES)/IMG_SOLVERS)*3;
22	
23	    for (int switch_idx=0; switch_idx<IMG_SOLVERS_PER_SWITCH; switch_idx++) {
24	        // Get packet ID for routing from specific index. Packet ID is automatically
25	        // given at compile time and must be fetched indirectly via an index.
26	        uint32 pkt_id = getPacketid(px_xyz_out, switch_idx);
27	        writeHeader(px_xyz_out, pkt_type, pkt_id);
28	
29	        for (int px_idx=0; px_idx<px_components_per_ai; px_idx++) {
30	            float px_xyz_val = readincr(px_xyz_in);
31	        
32	            //printf("%d: switch_idx: %d | pkt_id: %d | px_xyz_val: %f | tlast: %d\n", 
33	            //        px_idx, switch_idx, pkt_id, px_xyz_val, px_idx==(16*3)-1);
34	
35	            writeincr(px_xyz_out, px_xyz_val, px_idx==(px_components_per_ai-1));
36	        }
37	    }
38	}
