40	void data_broadcast_kern(input_stream<float>* __restrict slowtime_in,
41	                         input_buffer<cfloat, extents<RC_SAMPLES>>& __restrict rc_in,
42	                         output_stream<float>* __restrict slowtime_out,
43	                         output_buffer<cfloat, extents<RC_SAMPLES>>& __restrict rc_out) {
44	
45	    // Input and output iterators for range compressed samples
46	    auto rc_in_iter = aie::begin_vector<16>(rc_in);
47	    auto rc_out_iter = aie::begin_vector<16>(rc_out);
48	    
49	    // Write out slowtime data
50	    writeincr(slowtime_out, readincr_v<4>(slowtime_in));
51	    
52	    // Write out RC data
53	    for(unsigned i=0; i < RC_SAMPLES/16; i++) chess_prepare_for_pipelining {
54	        *rc_out_iter++ = *rc_in_iter++;
55	    }
56	}
