58	ImgReconstruct::ImgReconstruct(int id)
59	: m_id(id)
60	{}
61	
62	void ImgReconstruct::img_reconstruct_kern(input_buffer<float, extents<BC_ELEMENTS>>& __restrict slowtime_in,
63	                                          input_buffer<cfloat, extents<RC_SAMPLES>>& __restrict rc_in,
64	                                          input_pktstream *px_xyz_in,
65	                                          output_pktstream *img_out,
66	                                          int rtp_dump_img_in) {
67	    
68	    const int SAMPLES = (PULSES*RC_SAMPLES)/IMG_SOLVERS;
69	
70	    // Used for buffering X, Y, and Z target pixels from input
71	    // NOTE: Target pixels are stored as ints since thats the datatype associated
72	    // with pktswitch streams
73	    alignas(aie::vector_decl_align) float x_trgt_pxls[SAMPLES];
74	    alignas(aie::vector_decl_align) float y_trgt_pxls[SAMPLES];
75	    alignas(aie::vector_decl_align) float z_trgt_pxls[SAMPLES];
76	
